// Generated by scripts/generate-workflow-blueprints.ts (extra questions); edit the specs there and re-run rather than editing by hand.
import { o, s, type QuestionSet } from "@/lib/interview-questions";

const bank: QuestionSet = {
  subjective: [
    s(5, "Walk me through how a Claude model gets from raw data to serving a request on the Claude API.", "I'd split it into four planes. The data plane collects public web data, licensed data, opted-in user data and synthetic data, then filters and deduplicates it. The training plane pretrains a base model on large accelerator clusters and post-trains it with RLHF and Constitutional AI. The governance plane runs Responsible Scaling Policy evaluations, assigns an AI Safety Level and blocks release until the matching safeguards exist. The serving plane releases the model in stages, then handles Messages API traffic: key authentication, tiered rate limits, prompt caching, inference and streaming, usage metering and misuse monitoring. Enforcement findings feed back into safeguards and the next training cycle. Two invariants cut across every plane: capability never outruns safeguards, and tenants stay isolated."),
    s(4, "How would you design the filtering and deduplication stage for a web-scale pretraining corpus?", "I'd run it as a batch pipeline over sharded object storage, with every stage writing versioned outputs so a run can be reproduced. Stage one handles provenance and policy: record source and licence, and honour crawler rules such as robots.txt and the exclusion of password-protected pages. Stage two is quality and safety filtering with heuristics and classifiers, plus PII handling. Stage three is deduplication: exact hashing for identical documents, then MinHash with locality-sensitive hashing for near-duplicates, run at document and paragraph level. Stage four decontaminates by removing overlap with held-out evaluation sets. I'd keep per-stage drop statistics and spot-check samples so that one filter bug can't silently remove whole domains or languages."),
    s(4, "How do you stop evaluation benchmarks from leaking into training data, and why does it matter for a safety gate?", "If evaluation items leak into training, scores go up through memorisation rather than real capability. For capability benchmarks that only flatters the model. For dangerous-capability evals it is worse, because it corrupts the measurement the release gate depends on. I'd register every eval set with canary strings and n-gram fingerprints, then scan the training corpus against them before training starts. Sensitive evals stay in access-controlled stores that are never crawled or exported. I'd also keep private, regularly refreshed held-out sets and compare performance on public and private variants. A large gap between them is a contamination signal and should trigger investigation before the result counts toward an ASL decision."),
    s(3, "How would research teams plan the scale of a pretraining run and track capability trends?", "They fit scaling laws on smaller runs, which relate loss to parameters, data and compute, and use them to choose a compute-efficient model size and token budget for the target budget. During the run they track training loss and a suite of downstream evals at checkpoints, and compare the trajectory with the prediction. For safety, this trend tracking feeds the RSP: if checkpoints are on course to approach a capability threshold, the safeguards work has to start early rather than at release time. The key point is that the gate is only useful if capability is forecast ahead of time. Discovering a threshold crossing at the end leaves no time to build safeguards."),
    s(4, "A multi-week pretraining run on thousands of accelerators keeps losing nodes. How do you design for failure?", "At this scale, hardware failure is routine, so the design has to assume it. I'd take frequent asynchronous sharded checkpoints of weights, optimizer state, data-loader position and RNG state to durable storage, so a restart resumes deterministically. Health checks and straggler detection find bad nodes, and a scheduler swaps in hot spares and restarts from the last checkpoint automatically. I'd watch for loss spikes and NaNs, with a playbook to roll back to an earlier checkpoint, skip the offending data and adjust the learning rate. Checkpoint frequency is a trade-off: checkpointing too often costs throughput and storage bandwidth, while checkpointing too rarely wastes compute on every failure."),
    s(3, "Anthropic has described training and serving on Google TPUs, AWS Trainium and NVIDIA GPUs. What are the engineering trade-offs of that?", "The upside is capacity and resilience. You aren't limited by one vendor's supply, you can place workloads where capacity and cost-efficiency are best, and you can serve close to cloud partners like Bedrock and Vertex AI. The cost is engineering complexity. Kernels, compilers, parallelism strategies and numerics differ by chip, so you need a portable model definition, per-backend optimisation, and strong numerical equivalence tests so the same weights behave the same on every platform. Performance tuning is duplicated, and debugging spans multiple toolchains. To manage this, I'd keep a single source of truth for model code, add hardware-specific backends behind it, and run cross-platform eval regression suites before any deployment."),
    s(4, "How does the RLHF stage work, and how do you guard against reward hacking?", "Humans compare pairs of model responses. A reward or preference model learns to predict those preferences, and the policy is then optimised with RL against it, usually with a KL penalty that keeps it close to the supervised model. Reward hacking happens when the policy exploits weaknesses in the reward model: excessive length, sycophancy, confident-sounding but wrong answers, or gaming of test checks in coding tasks. Mitigations include a KL constraint, ensembles and periodic retraining of reward models on fresh comparisons, held-out human evaluation, and targeted evals for sycophancy and honesty. I'd also audit samples where reward is high but humans disagree, since those show exactly where the proxy diverges."),
    s(2, "How would you evaluate whether post-training produced the intended character, such as honesty and appropriate refusals?", "I'd turn the intended traits into concrete, testable behaviours and build an eval suite around them. Honesty evals check calibration, admitting uncertainty, and not inventing facts or citations. Sycophancy evals check whether the model changes a correct answer under user pressure. Refusal evals measure both sides: harmful requests should be declined, and benign but borderline requests should not be over-refused. Character consistency gets checked across long multi-turn conversations and personas. I'd combine automated graders with human review, track every metric per checkpoint, and treat a regression on either harmfulness or over-refusal as a release blocker. Optimising one side alone is the classic failure."),
    s(4, "Design the harness for dangerous-capability evaluations such as CBRN uplift and autonomy.", "I'd build an isolated, access-controlled evaluation environment, because both the questions and the transcripts are sensitive. Tasks cover knowledge probes, multi-step agentic tasks in sandboxes with tools, and expert-graded uplift studies that compare people with and without model access. Each eval is versioned, has a pre-registered threshold tied to an RSP capability threshold, and runs on the final candidate and on any snapshot meant for release. Results go into a capability report that records the elicitation used, such as scaffolding, tool access and best-of-n sampling. Sandboxes for autonomy tasks need network egress controls and monitoring. Nothing produced in them should be able to touch production systems."),
    s(3, "Why must dangerous-capability evaluations make a serious effort to elicit the model's best performance?", "The gate asks whether the model could provide dangerous capability, not whether it did so under a lazy prompt. If you under-elicit, you understate capability and might deploy with too little protection. Real attackers will use good prompting, agent scaffolds, tools, fine-tuning where it's available and many attempts. So evaluators should use strong prompts, chain-of-thought, tool use, multiple samples and, where it makes sense, helpful-only variants without refusal training. They should also add a safety margin for capability gains likely to come from better scaffolding after release. The conservative principle is that uncertainty about whether a threshold is crossed should push you toward assuming it is crossed."),
    s(4, "What kinds of safeguards does the ASL-3 standard involve?", "Anthropic's ASL-3 standard has two parts, which it publicly activated with Claude Opus 4 in 2025. Deployment safeguards aim to stop misuse for CBRN weapons. They include real-time constitutional classifiers on inputs and outputs, ongoing jailbreak monitoring, a bug bounty for universal jailbreaks, and rapid response to patch new attacks. Security safeguards aim to prevent theft of model weights. They include stronger access controls, two-party authorisation for sensitive access, and egress bandwidth controls that make large exfiltration hard to do and easy to detect. Both parts have to be judged adequate before deployment. A model that needs ASL-3 does not ship under ASL-2 protections just because the release date is near."),
    s(4, "How would you protect frontier model weights from theft, both by insiders and by external attackers?", "I'd treat the weights as a crown-jewel asset. Store them encrypted, with keys held in hardware-backed key management. Restrict access to a small, audited set of identities using least privilege, and require two-party approval for any sensitive operation, such as copying weights or accessing them in plaintext. Serving nodes load weights into hardened environments with no general interactive access. Egress bandwidth limits and monitoring on the networks that hold weights make a bulk copy slow and noisy. I'd add full audit logs, anomaly detection, supply-chain controls on serving software, and regular red-team exercises. Insider risk gets the same rigour as external risk, because one compromised credential shouldn't be enough."),
    s(2, "How would you integrate pre-deployment testing by external partners such as government AI safety institutes without weakening security?", "Give them access through a controlled channel rather than handing over weights. For example, an API endpoint to a specific pre-release snapshot, with logging, rate limits and scoped credentials that expire after the testing window. Agree in advance on the domains they will test, the timeline and how findings are reported, so their results arrive in time to inform the ASL decision rather than after launch. Sensitive test content and transcripts stay protected on both sides. Findings go into the same tracking system as internal red-team issues, with owners and resolutions. The value is independent scrutiny. The risk is leakage of an unreleased model, so isolation and auditing matter."),
    s(4, "How would you design the staged release from limited testers to general availability, including rollback?", "Define stages as ring deployments: internal use, trusted testers under agreements, limited preview, then GA across the API, apps and cloud partners. Each ring has exit criteria: no unresolved severe safety findings, classifier and abuse metrics within bounds, error rates and latency within SLO, and enough capacity for the next ring. Model routing is controlled by configuration, so an organisation's access can be widened or pulled back without redeploying. Rollback means removing access to the new model ID or tightening safeguards. You don't silently swap weights behind a pinned model ID, because customers depend on stable behaviour. Release artefacts such as the system card and usage policy updates are finalised before GA, not after."),
    s(3, "The same model is offered on the Claude API, Amazon Bedrock and Google Cloud Vertex AI. How do you keep behaviour and safeguards consistent?", "Treat the model as an immutable versioned artefact: the same weights, tokenizer and default configuration, identified by a dated snapshot ID. Every surface gets a conformance test suite that checks outputs, tool-use formats, stop behaviour and safety behaviour against reference results. Usage policies and acceptable-use requirements apply on every surface, though the partner platforms run their own authentication, quotas and billing. Feature availability, such as particular beta features, can lag on partner platforms. So I'd publish a feature matrix rather than assume parity. I'd also monitor cross-surface metrics, so a numerical or configuration drift on one platform shows up as an anomaly instead of waiting for a customer report."),
    s(2, "What belongs in a model or system card, and why publish one?", "A system card describes what the model is and how it was tested. That covers training data at a high level, intended uses, capability benchmark results, safety evaluations including dangerous-capability results and the AI Safety Level decision, red-teaming and external testing, alignment and welfare-related findings where relevant, and known limitations. Publishing it creates accountability. Outsiders can scrutinise the evidence behind a deployment decision, developers learn where the model is weak, and the lab commits to a record it can be held to. The engineering implication is that eval pipelines must produce reproducible, reportable results. If a number can't be traced back to a versioned eval run, it shouldn't appear in the card."),
    s(4, "How would you design API key authentication for the Messages API, including handling leaked keys?", "The client sends the key in the x-api-key header, alongside an anthropic-version header. At the edge, I'd hash the presented key and look it up in a replicated key store that maps it to organisation, workspace, tier and status, cached briefly so revocation propagates within seconds. Keys are shown once at creation, stored only as hashes, scoped to workspaces, and can be revoked from the console. Anthropic participates in secret-scanning programmes so that keys leaked to public repositories can be detected and deactivated. Every request is attributed to a key and organisation for rate limiting, billing and abuse investigation. Failed authentication returns 401 quickly, without touching inference capacity."),
    s(5, "Rate limits apply to requests, input tokens and output tokens per minute. How do you enforce an output-token limit before the output exists?", "Anthropic documents its limits as token buckets, which refill continuously up to a maximum rather than resetting at fixed intervals. For output tokens, admission uses an estimate based on the request's max_tokens, then reconciles against actual output when the response completes. Input tokens can be counted at admission, and for most current models cached reads don't count toward the input-token limit. The buckets live in a low-latency distributed store keyed by organisation and model. To keep latency down I'd allow small, bounded over-admission rather than a strongly consistent global counter. A rejection returns 429 with a retry-after header and rate-limit headers describing remaining capacity."),
    s(4, "What is the difference between a 429 and a 529 from the Claude API, and how should clients and the server behave?", "A 429 means this organisation exceeded its own rate limit. It is the caller's quota, and the fix is to slow down, respect retry-after, or move to a higher tier. A 529 overloaded_error means the service as a whole is temporarily overloaded, independent of the caller's quota. Clients should retry both with exponential backoff and jitter, cap total retries, and avoid synchronised retry storms. The official SDKs retry certain errors by default. On the server, load shedding should happen early and cheaply at admission, before tokens are processed, and priority or committed capacity can be protected while best-effort traffic is shed first."),
    s(5, "How do you guarantee that prompt caching never lets one tenant read or influence another tenant's cached context?", "Make tenant identity part of the cache key, not a check performed after lookup. The key combines the isolation scope, which Anthropic documents as at least the organisation, with the model and a hash of the exact prefix up to the breakpoint. Two tenants with byte-identical prompts therefore get different entries. There is no cross-tenant cache to probe, so no timing side channel. Cache storage is in-memory or short-lived, with TTL eviction. Entries are never written to training data or logs as content. I'd add tests that send identical prefixes from different organisations and assert there are no cache reads, plus audits on the key-construction code, since a bug there would be a cross-tenant data leak."),
    s(4, "How is the cache key structured for prompt caching, and what invalidates a cache entry?", "The cacheable prefix is built in a fixed order: tools, then system, then messages, up to a block marked with cache_control. You can set up to four breakpoints. A hit requires the prefix to be identical up to that breakpoint, so any change earlier in the order invalidates everything after it. Editing a tool definition invalidates the system and message cache. Editing the system prompt invalidates the messages. Changes to some settings, such as images or tool_choice, can also break hits. Entries expire by TTL: five minutes by default, refreshed on each hit, with an optional one-hour TTL. The design advice is to put stable content first and volatile content last."),
    s(3, "Where would cached prompt state live on the serving side, and what trade-offs does the TTL involve?", "What gets reused is the attention key-value state computed for the prefix, so the model skips recomputing it. That state is large, so it lives in accelerator memory or a nearby fast tier, and routing needs to send requests to replicas that hold, or can quickly fetch, the prefix state. TTL is a cost and capacity trade-off. A longer TTL raises hit rates for bursty workloads but holds scarce memory longer. That is why the one-hour option has a higher write price than the five-minute default, and why the five-minute TTL refreshes on each hit. Eviction must be safe: a miss only costs recomputation, never correctness, so the cache can be dropped under pressure."),
    s(4, "How would you design token streaming, and what happens if the connection fails mid-stream?", "The Messages API streams over server-sent events with a typed sequence: message_start, content_block_start, repeated content_block_delta, content_block_stop, message_delta carrying the stop reason and usage, then message_stop, plus ping events. Typed blocks let text and tool-use JSON stream on the same channel. Errors can also arrive as an event mid-stream, after a 200 has been sent, so clients must handle in-stream error events. If the connection drops, the request does not resume. The client retries, and the prefix cache makes the retry cheaper. Server-side, generation should be cancelled when the client disconnects, to free capacity, and usage should be billed for the tokens actually processed."),
    s(4, "How would you design usage metering so billing and the console are accurate and never double-count?", "Each request has a unique request ID, returned to the caller in a response header. At completion, the serving layer emits one usage event with organisation, workspace, key, model, input tokens, cache-creation tokens, cache-read tokens and output tokens. Events go to a durable log with at-least-once delivery, and consumers deduplicate on request ID, which gives effectively-once aggregation. Real-time counters for the console can be approximate. Invoices come from the reconciled ledger. I'd keep pricing in versioned rate tables applied at aggregation time, so a price change never rewrites history. Daily reconciliation compares serving logs, rate-limit counters and the ledger to catch dropped or duplicated events."),
    s(3, "Give a back-of-the-envelope capacity estimate approach for an LLM API endpoint.", "I'd state assumptions explicitly rather than quote real figures. Start with peak requests per second, average input and output tokens per request, and expected cache hit rate. Prefill cost scales with uncached input tokens, and decode cost scales with output tokens. Decode is usually the bottleneck because it runs token by token. Then measure a single replica's sustainable throughput at the target latency, for example time to first token and tokens per second per stream, under realistic batching. Divide peak load by per-replica throughput and add headroom for failures, deployments and burst. Caching mainly reduces prefill, so a high hit rate raises effective capacity for long-context workloads more than for short chatty ones."),
    s(4, "How do you monitor for policy violations at API scale while respecting user privacy?", "Use layers. Automated classifiers score traffic for high-severity categories in real time or near real time, and constitutional classifiers block certain CBRN content inline. Account-level signals, such as volume patterns and repeated flagged requests, feed trust-and-safety review, with enforcement that ranges from warnings to suspension. For understanding aggregate patterns, Anthropic has described Clio, which summarises and clusters conversations so analysts see aggregated trends rather than individual chats. Access to raw content is restricted, logged and justified case by case. Retention follows published policies and contractual terms such as zero-data-retention arrangements. I'd track classifier false positives carefully, because over-blocking legitimate developers is also a failure."),
    s(3, "How do enforcement findings and misuse patterns feed back into the next model, and what data governance applies?", "Misuse findings mostly feed the safeguards first. New jailbreak patterns become classifier training data and red-team cases, and recurring harmful request types become eval items and post-training targets for the next model. Governance is strict about what can be used. By default, commercial API inputs and outputs are not used to train models. Consumer conversations are used only if the user opted in. Flagged content may be reviewed for trust and safety under published policy. In practice, I'd pass abstracted patterns and synthetic reproductions into training rather than raw customer data, tag every dataset with its provenance and allowed uses, and have the pipeline refuse data lacking a permitted-use tag."),
    s(2, "When would you recommend the Message Batches API over real-time Messages calls?", "Use batches for large workloads that aren't latency-sensitive, such as classification, evaluation runs, document processing or data generation. The Batches API processes requests asynchronously, typically completing within 24 hours, and is priced at a discount compared with standard calls. From the provider's side, batches are easier to schedule into idle capacity. That lets you smooth load and protect real-time traffic. Batches can also be combined with prompt caching for shared prefixes. The trade-offs are no streaming, no interactive tool loops, and result retrieval that must handle partial failures per request. Real-time calls remain the right choice for chat, agents and anything user-facing."),
    s(3, "How should model versioning and deprecation work so customers aren't surprised by behaviour changes?", "Publish immutable, dated snapshot IDs and, optionally, aliases that move to newer snapshots. Production customers should pin snapshots, because the snapshot's behaviour is fixed. Aliases suit experimentation. Changes to a model's behaviour ship as a new snapshot rather than as silent in-place updates, apart from safety-critical safeguard changes in the classifier layer. Deprecation follows a published schedule with advance notice, deprecation status in docs and console, and a retirement date after which requests fail clearly. Anthropic has also published commitments about preserving retired model weights. Internally, I'd track usage by model ID so the team can contact remaining users before retirement."),
    s(3, "Inline safety classifiers add latency and can conflict with streaming. How would you balance that trade-off?", "Score the input before generation starts, since that is cheap relative to decoding and lets you block early. For outputs, run a streaming classifier over chunks as they are generated. If it fires, stop the stream and return a refusal instead of waiting for the full response. The classifier has to be fast and calibrated, so you tune thresholds per harm category. The aim is to block high-severity content such as CBRN uplift with high recall, while keeping false positives on legitimate science questions low. Apply the strictest inline checks only where the risk justifies them, rely on asynchronous monitoring for lower-severity policies, and measure added latency as a first-class SLO."),
  ],
  objective: [
    o(5, "What is the default lifetime of a prompt cache entry on the Claude API?", ["30 seconds, fixed","5 minutes, refreshed each time the cache is read","24 hours","Until the organisation clears it manually"], 1, "The default ephemeral cache lasts five minutes and is refreshed on each hit. A longer one-hour TTL is available as an option at a higher write price."),
    o(4, "In what order are request components combined to form the cacheable prefix?", ["messages, system, tools","system, messages, tools","tools, system, messages","Order does not matter; matching is content-based"], 2, "The prefix is built as tools, then system, then messages. A change earlier in that order invalidates the cache for everything after it."),
    o(4, "Which response usage field tells you that tokens were served from the prompt cache?", ["cache_creation_input_tokens","cache_read_input_tokens","output_tokens","stop_reason"], 1, "cache_read_input_tokens counts tokens read from cache. cache_creation_input_tokens counts tokens written to cache on a miss."),
    o(4, "Which algorithm does Anthropic document for its API rate limits?", ["Fixed window counter reset every minute","Token bucket with continuous replenishment","Leaky bucket with no burst capacity","Sliding log of every request"], 1, "Anthropic's documentation says capacity replenishes continuously up to a maximum, which is the token bucket model, rather than resetting at fixed intervals."),
    o(3, "What does an HTTP 529 overloaded_error from the Claude API indicate?", ["The caller's API key is invalid","The caller exceeded its own rate limit","The service is temporarily overloaded across users","The request body was malformed"], 2, "529 signals service-wide overload. 429 is the per-organisation rate-limit response."),
    o(4, "After receiving a 429, what should a well-behaved client do first?", ["Retry immediately in a tight loop","Wait according to the retry-after header, using backoff with jitter","Rotate to a different organisation's API key","Switch to a larger max_tokens value"], 1, "The 429 includes a retry-after header, and backoff with jitter avoids synchronised retry storms. Using other tenants' keys would violate policy."),
    o(3, "How many cache_control breakpoints can a single request define?", ["1","2","4","Unlimited"], 2, "The API allows up to four cache breakpoints per request, which lets you cache tools, system and conversation segments separately."),
    o(4, "What happens in the supervised phase of Constitutional AI?", ["Humans write gold answers for every harmful prompt","The model critiques and revises its own responses using constitutional principles, and is fine-tuned on the revisions","The model is pretrained again on filtered web data","A classifier deletes harmful tokens at inference time"], 1, "In the supervised phase the model critiques and revises its own outputs against the constitution, and is then fine-tuned on the revised responses. The RL phase uses AI feedback."),
    o(3, "With which model did Anthropic first activate ASL-3 protections?", ["Claude 2","Claude 3 Opus","Claude Opus 4","Claude Instant"], 2, "In May 2025 Anthropic activated ASL-3 deployment and security standards alongside the launch of Claude Opus 4."),
    o(4, "Which capability areas are central to the Responsible Scaling Policy's capability thresholds?", ["Translation quality and summarisation","CBRN weapons and autonomous AI research and development","Code formatting and latency","Image generation and audio"], 1, "The RSP defines capability thresholds around CBRN weapons uplift and autonomous AI R&D, and those thresholds trigger stronger required safeguards."),
    o(5, "Evaluations show a model crosses a capability threshold, but the required safeguards are not ready. What does the RSP require?", ["Ship on schedule and add safeguards later","Ship only to enterprise customers","Do not deploy until the required safeguards are in place, or mitigate the model","Publish the results and let users decide"], 2, "The RSP's core commitment is that a model is not deployed without the safeguards matching its capability level."),
    o(4, "Which statement about prompt cache isolation is correct?", ["Identical prompts from any customer share one cache entry","Caches are isolated so different organisations never share cache entries","Caches are shared within a cloud region","Isolation applies only to the one-hour TTL"], 1, "Anthropic documents that prompt caches are isolated between organisations, so identical prefixes from different tenants never produce cross-tenant hits."),
    o(4, "What is required for a cache hit?", ["Semantic similarity above a threshold","An identical prefix up to the cache breakpoint","The same API key and any prompt","The same conversation ID"], 1, "Caching uses exact prefix matching, so even small changes before the breakpoint cause a miss."),
    o(3, "A developer edits one tool description while keeping the system prompt identical. What happens to caching?", ["Only the tools segment misses; the system prompt still hits","The whole cached prefix is invalidated, because tools come first","Nothing; tools are excluded from caching","The cache TTL is extended"], 1, "Tools sit at the start of the prefix, so changing them alters every later part of the prefix and invalidates the system and message cache."),
    o(4, "What transport does the Messages API use for streaming responses?", ["WebSockets","gRPC bidirectional streams","Server-sent events","Long polling"], 2, "Streaming uses server-sent events with typed events such as message_start, content_block_delta and message_stop."),
    o(3, "Which headers authenticate and version a direct Claude API request?", ["Authorization: Basic and X-Version","x-api-key and anthropic-version","Cookie and User-Agent","api-token and model-version"], 1, "Direct API calls send the key in x-api-key and require the anthropic-version header."),
    o(3, "What best describes the Message Batches API?", ["Synchronous, streamed responses at premium pricing","Asynchronous processing of many requests, typically within 24 hours, at a discount","A way to bypass rate limits for real-time chat","A fine-tuning endpoint"], 1, "Batches are processed asynchronously, usually within 24 hours, at a discount compared with standard calls, which suits latency-tolerant bulk work."),
    o(3, "Why deduplicate pretraining data?", ["To increase the total token count","To reduce memorisation, wasted compute and evaluation contamination","To remove every non-English text","To make training non-deterministic"], 1, "Duplicates encourage memorisation, waste compute and can leak evaluation items. Deduplication improves data efficiency and makes measurement more trustworthy."),
    o(3, "Which is an example of an ASL-3 security safeguard for model weights?", ["Publishing weights for transparency","Egress bandwidth controls and two-party authorisation for sensitive access","Removing all access logs to protect privacy","Raising API rate limits"], 1, "Anthropic described egress bandwidth controls and multi-party access controls among its ASL-3 weight-protection measures."),
    o(3, "What are constitutional classifiers used for in Claude's deployment safeguards?", ["Tokenising input text","Screening inputs and outputs to block harmful content such as CBRN uplift, including jailbreak attempts","Routing requests to the cheapest model","Computing billing totals"], 1, "Constitutional classifiers are trained from a constitution of allowed and disallowed content and screen inputs and outputs. They are a key ASL-3 deployment safeguard."),
    o(3, "In RLHF, what is reward hacking?", ["Attackers stealing the reward model","The policy exploiting weaknesses in the learned reward to score highly without truly being better","Humans labelling too slowly","Rewards overflowing numerically"], 1, "The policy optimises a proxy reward, so it can learn behaviours such as verbosity or sycophancy that the reward model overrates."),
    o(4, "By default, are inputs and outputs from commercial Claude API customers used to train Anthropic's models?", ["Yes, always","No, not by default","Only for cached prompts","Only for requests that hit rate limits"], 1, "Anthropic's commercial terms state that it does not train on customer API data by default. Consumer data is used only when the user opts in."),
    o(3, "How is a cache read priced relative to the base input token price, per Anthropic's public pricing?", ["The same as base input","About 10% of base input","Twice base input","Free with no charge"], 1, "Cache reads are billed at a fraction of base input, published as 0.1x. Five-minute cache writes cost 1.25x base input."),
    o(3, "A request marks a 300-token system prompt with cache_control and never sees cache writes. Why?", ["cache_control is only allowed on messages","The prefix is below the model's minimum cacheable length, so it is processed without caching","Caching requires the Batches API","The anthropic-version header disables caching"], 1, "Each model has a minimum cacheable prompt length, for example 1,024 tokens for many models. Shorter prefixes are processed normally without caching."),
    o(2, "How do organisations usually get higher standard Claude API rate limits?", ["By sending more 429-triggering traffic","By advancing through usage tiers based on spend, or by arranging custom limits with sales","By creating many free accounts","Limits are identical for everyone"], 1, "Rate limits increase automatically as organisations move up usage tiers, and custom limits are available through Anthropic's sales team."),
    o(2, "For most current Claude models, how do cache read tokens interact with the input-tokens-per-minute limit?", ["They count double","They do not count toward the input-tokens-per-minute limit","They count only toward requests per minute","They count toward output tokens"], 1, "Anthropic documents that cached input tokens read from cache do not count toward ITPM for most models, so caching also increases effective throughput."),
    o(2, "What is the main safety benefit of staged release before general availability?", ["It lowers training cost","It exposes the model to progressively wider use, so real-world issues surface while access is still limited and reversible","It removes the need for evaluations","It guarantees zero jailbreaks"], 1, "Staged rings limit the blast radius and give time to detect misuse and failures before broad deployment."),
    o(2, "Which organisations has Anthropic publicly described as doing pre-deployment testing of its models?", ["Only internal teams","Government AI safety institutes in the US and the UK","Random customers selected by lottery","Cloud partners' billing teams"], 1, "Anthropic has published that the US and UK government AI safety and security institutes tested models before deployment."),
    o(3, "Usage events are delivered at-least-once. How do you stop customers from being double-billed?", ["Switch to at-most-once delivery","Deduplicate events on a unique request ID before aggregation","Bill an average per day","Ignore events that arrive late"], 1, "Idempotent consumers keyed on request ID turn at-least-once delivery into effectively-once aggregation without losing events."),
    o(2, "What is Clio, as described by Anthropic?", ["A model-weights encryption tool","A privacy-preserving system for analysing aggregate patterns of Claude usage","A rate-limiting service","A tokenizer"], 1, "Clio summarises and clusters conversations so analysts can study usage and misuse trends in aggregate without reading individual chats."),
  ],
};
export default bank;
